import math

def legendre(n, p):
    """Calculates the exponent of prime p in n!"""
    count = 0
    power_of_p = p
    while power_of_p <= n:
        count += n // power_of_p
        if n // power_of_p < p: # Optimization to prevent overflow if n is very large, though not strictly needed here
            break
        power_of_p *= p
    return count

def omega_M(n):
    """
    Calculates omega(n! / 2023), where 2023 = 7 * 17^2.
    This is the number of distinct prime factors of M = n! / 2023.
    """
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, n + 1, p):
                is_prime[i] = False

    omega = 0

    for p in primes:
        is_factor = False

        if p != 7 and p != 17:
            # For primes other than 7 and 17, they are factors of M if they are factors of n!, which is true if p <= n.
            # Since we only iterate over primes p <= n, they are factors of n!.
            is_factor = True
        else:
            # Handle p=7 and p=17
            E_p_n_factorial = legendre(n, p)

            if p == 7:
                # E_7(2023) = 1
                if E_p_n_factorial > 1:
                    is_factor = True
            elif p == 17:
                # E_17(2023) = 2
                if E_p_n_factorial > 2:
                    is_factor = True

        if is_factor:
            omega += 1

    return omega

def check_n(n):
    omega = omega_M(n)
    N = 2**omega
    return omega, N

