import math

def prime_factorization_count(m):
    """Calculates omega(m), the number of distinct prime factors of m."""
    if m <= 0:
        return 0
    count = 0
    d = 2
    temp_m = m
    while d * d <= temp_m:
        if temp_m % d == 0:
            count += 1
            while temp_m % d == 0:
                temp_m //= d
        d += 1
    if temp_m > 1:
        count += 1
    return count

def factorial(n):
    return math.factorial(n)

# The constant is 2023 = 7 * 17^2
DIVISOR = 2023

results = {}

for n in range(1, 21):
    n_factorial = factorial(n)

    if n_factorial % DIVISOR == 0:
        M = n_factorial // DIVISOR
        omega_M = prime_factorization_count(M)
        N = 2**omega_M
        results[n] = N
    else:
        # If n! is not divisible by 2023, M is not an integer, 
        # so omega(M) is undefined in the standard context.
        # We will represent this as 'N/A' for recording purposes, 
        # as no valid integer M exists to calculate N.
        results[n] = "N/A (n! not divisible by 2023)"

print("n, N")
for n, N in results.items():
    print(f"{n}, {N}")

def count_primes(n):
    count = 0
    for i in range(2, n + 1):
        is_prime = True
        for j in range(2, int(i**0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
    return count

